"""
One-off seed of data/rental_rates.json 'contracts' (2026-09-09): every public multi-year AI compute contract found in a
two-pass web research sweep (neocloud GPU rentals; hyperscaler cloud commitments; data-centre leases), Jan 2025 - Sep 2026.
Kept in the repo so the classification and the arithmetic behind each derived rate are reproducible. Run once:
    python engine/deals_seed.py
Fields per row:
  kind        gpu-rental | cloud-commit | dc-lease | backstop | reference | acv | expected
  value_usd_b total contract value (base term), USD billions; null when undisclosed
  term_years  base term; null when undisclosed
  gpus, chip, mw, mw_basis (IT | facility | not stated)
  source      primary | press, multiple | press, single   (who disclosed the key figures)
  status      active | terminated | loi | expected
  use         whether the row may enter the long-term contract medians (set by classify())
Derived: per_gpu_hr = value / (term x 8760 x gpus); per_mw_yr_musd = value x 1000 / (term x mw).
"""
import json, datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
HOURS = 8760.0
TODAY = "2026-09-09"

R = []
def row(parties, announced, kind, value=None, term=None, gpus=None, chip=None, mw=None, mw_basis="not stated", url="", source="primary", note="", status="active", assumption=None, acv=None, per_gpu_hr=None, use=None, cancellable=False):
    R.append({"parties": parties, "announced": announced, "kind": kind, "value_usd_b": value, "term_years": term, "gpus": gpus, "chip": chip, "mw": mw, "mw_basis": mw_basis,
              "url": url, "source": source, "note": note, "status": status, "assumption": assumption, "acv_per_it_mw_yr_musd": acv, "per_gpu_hr_stated": per_gpu_hr,
              "use_override": use, "cancellable": cancellable})

