def classify(r):
    """Derived rates and whether a row may enter the medians."""
    v, t, g, mw = r["value_usd_b"], r["term_years"], r["gpus"], r["mw"]
    per_gpu = r.pop("per_gpu_hr_stated", None)
    computed = False
    if per_gpu is None and v and t and g:
        per_gpu = v * 1e9 / (t * HOURS * g)
        computed = True
    r["per_gpu_hr"] = round(per_gpu, 2) if per_gpu else None
    r["computed"] = computed if per_gpu else False
    r["per_mw_yr_musd"] = round(v * 1e3 / (t * mw), 2) if (v and t and mw) else None
    chip = (r.get("chip") or "")
    blackwell_ultra = ("GB300" in chip) or ("B300" in chip)
    ov = r.pop("use_override", None)
    auto = bool(r["kind"] in ("gpu-rental", "reference") and r["status"] == "active" and r["per_gpu_hr"] and blackwell_ultra and (t is None or t >= 3) and not r.get("cancellable"))
    r["use"] = auto if ov is None else (ov and bool(r["per_gpu_hr"]))
    r["read_on"] = TODAY
    return r


def main():
    p = ROOT / "data" / "rental_rates.json"
    d = json.load(open(p, encoding="utf-8"))
    d["contracts"] = [classify(dict(r)) for r in R]
    d["_comment"] = [c for c in d["_comment"] if not c.startswith("contracts:") and "computed' says whether" not in c and "by the source. 'use'" not in c]
    i = next(i for i, c in enumerate(d["_comment"]) if c.startswith("The rental scenario's term structure"))
    d["_comment"][i:i] = [
        "contracts: every public multi-year AI compute contract found (Jan 2025 - Sep 2026), classified by 'kind': gpu-rental (a",
        "  neocloud sells GPU compute), cloud-commit (a lab commits spend to a hyperscaler), dc-lease (powered shell / colocation",
        "  hosting GPUs), backstop (NVIDIA rent-back guarantees), reference (third-party market quotes), expected, acv (stated",
        "  $/MW-year). per_gpu_hr = value / (term x 8760 x GPUs) where all three are disclosed ('computed'); per_mw_yr_musd =",
        "  value / (term x MW). 'use' marks the rows that enter the long-term contract medians: active GPU rentals (and market",
        "  references) on GB300 / B300 with a derivable rate. 'source' says who disclosed the figures; 'status' flags LOIs,",
        "  terminated and expected deals. The daily 'deals' step queues new announcements in data/deal_candidates.json for review;",
        "  engine/deals_seed.py holds the seed list and the arithmetic. Rows do not refresh automatically.",
    ]
    json.dump(d, open(p, "w", encoding="utf-8"), indent=1)
    used = [c for c in d["contracts"] if c["use"]]
    print("%d contracts; %d enter the medians:" % (len(d["contracts"]), len(used)))
    for c in used:
        print("  %-60s $%.2f/GPU-hr  gpus=%s" % (c["parties"][:60], c["per_gpu_hr"], c["gpus"]))


if __name__ == "__main__":
    main()
